mapper.update:
UPDATE video
SET status = #{newStatus}
WHERE vid = #{vid}
    AND status = #{oldStatus}
    AND deleted_at IS NULL

mapper.select:
SELECT v.vid AS vid, v.uid AS uid, v.title AS title, v.cover_url AS coverUrl, v.duration AS duration, vs.play_times AS playTimes, vs.comment_times AS commentTimes, v.created_at AS createdAt, u.nickname AS nickname FROM video v INNER JOIN video_status vs ON vs.vid = v.vid INNER JOIN users u ON u.id = v.uid WHERE v.status = 1 AND v.visibility = 0 AND v.deleted_at IS NULL
AND ( v.created_at < #{cursorCreatedAt} OR ( v.created_at = #{cursorCreatedAt} AND v.vid < #{cursorVid} ) )
ORDER BY v.created_at DESC, v.vid DESC LIMIT #{size}
